;Волк ЖораJR_SM=-JR_+PL        DW J0+SM,J1+SM,J2+SM,J3+SMJ0      DB "Возьми, авось с голодухи и это",CR        DB "в радость будет.",SOBES        DB "Извини, бабуля, но я таким разом",CR        DB "лучше тебя скушаю.",ENDJ1      DB "Здравствуй, Жорик!",SOBES        DB "И тебе не болеть, бабуля!",HERO        DB "Ты чего тут опять расселся?",SOBES        DB "Да кушать очень хочется. У тебя",CR        DB "случайно нет ничего вкусненького?",HERO        DB "Кой-чего есть, но я собралась",CR        DB "в дорогу.",SOBES        DB "Значит, мне придется полакомиться",CR        DB "бабушкой. Зайцы-то совсем не",CR        DB "уродились...",DIALOG,2J2      DB "Пропусти меня, я очень тороплюсь!",SOBES        DB "Да я завсегда! Но волчий инстинкт",CR        DB "да пустой желудок погодить мне",CR        DB "велят.",ENDJ3      DB "Кушай, серый, тебе понравится.",SOBES        DB "Красная Шапочка, конечно,",CR        DB "питательнее, ну да ничего - это",CR        DB "тоже пойдет...",NEXT        DB "Схватив бутерброд, довольный волк",CR        DB "направился в лес.",SCRPT,2;           123456789-123456789-123456789-123JEND